<script setup lang="ts">
import {onMounted,ref} from 'vue';
import type {ApiClient} from '@kuaixie/sdk';
import {t,formatAmount,formatDate,uiErrorMessage} from '@kuaixie/i18n';
import ShopOrders from './ShopOrders.vue';
import {useShop,shopStatusKey} from './useShop';
const props=defineProps<{client:ApiClient;admin?:boolean}>();const p=useShop(props.client,async(a,b)=>window.confirm(a+'\n'+b),'web',!!props.admin),product=ref(''),selectedOrders=ref<{id:string;name:string}|null>(null);
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await p.run(async()=>{const result=await props.client.files.upload(file,file.name,'store_license');if(p.isCurrent())p.application.licenseUploadId=result.id});input.value=''}
async function download(id:string){try{if(!p.isCurrent())return;const bytes=await props.client.files.download(id);if(!p.isCurrent())return;const url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'}));const a=document.createElement('a');a.href=url;a.download='license-'+id;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(p.isCurrent())p.error.value=uiErrorMessage(e)}}
onMounted(()=>{void p.load();if(!props.admin)void p.loadProducts()});
</script>
<template><section class="shop-centre business-card"><h2>{{t('shop.title')}}</h2><p>{{t('shop.boundary')}}</p><p v-if="p.error.value" role="alert">{{p.error.value}}</p><p v-if="p.notice.value" role="status">{{p.notice.value}}</p><button :disabled="p.loading.value||p.busy.value" @click="p.load()">{{t('common.retry')}}</button>
<template v-if="admin"><label>{{t('case.note')}}<textarea v-model="p.note.value" maxlength="1000"/></label><article v-for="row in p.queue.value" :key="row.id"><h3>{{row.business_name}} · {{t(shopStatusKey(row.status))}}</h3><p>{{row.unified_social_credit_code}} · {{row.legal_representative}} · {{row.application_channel}}</p><p>{{row.review_note}}</p><button :disabled="p.busy.value" @click="download(row.license_upload_id)">{{t('shop.license')}}</button><template v-if="row.status==='pending'"><button :disabled="p.busy.value" @click="p.review(row,true)">{{t('shop.approve')}}</button><button :disabled="p.busy.value" @click="p.review(row,false)">{{t('shop.reject')}}</button></template><template v-if="row.store_id&&row.store_status"><button @click="selectedOrders={id:row.store_id,name:row.business_name}">{{t('shopOrders.view')}}</button><p>{{t(shopStatusKey(row.store_status))}}</p><button v-if="row.store_status!=='suspended'" :disabled="p.busy.value" @click="p.status(row.store_id,row.store_status,'suspended')">{{t('shop.suspend')}}</button><button v-else :disabled="p.busy.value" @click="p.status(row.store_id,row.store_status,'paused')">{{t('shop.restore')}}</button></template></article><button v-if="p.more.value" @click="p.load(true)">{{t('account.more')}}</button><ShopOrders :client="client" admin :store-id="selectedOrders?.id" :store-name="selectedOrders?.name"/></template>
<template v-else><template v-if="p.state.value?.store"><ShopOrders :client="client" :store-id="p.state.value.store.id" :store-name="p.state.value.store.name"/><form @submit.prevent="p.save()"><h3>{{t(shopStatusKey(p.state.value.store.status))}}</h3><label>{{t('shop.name')}}<input v-model="p.edit.name" maxlength="200" required/></label><label>{{t('shop.description')}}<textarea v-model="p.edit.description" maxlength="1000"/></label><p>{{t('shop.feeReference')}} {{p.state.value.store.matching_fee_rate}}%</p><button :disabled="p.busy.value">{{t('account.save')}}</button></form><button v-if="p.state.value.store.status!=='suspended'" :disabled="p.busy.value" @click="p.status(p.state.value.store.id,p.state.value.store.status,p.state.value.store.status==='active'?'paused':'active')">{{t(p.state.value.store.status==='active'?'shop.pause':'shop.open')}}</button><button @click="p.preview(p.state.value.store.id)">{{t('shop.preview')}}</button><label>{{t('shop.products')}}<select v-model="product"><option value="">—</option><option v-for="row in p.products.value" :key="String(row.id)" :value="String(row.id)">{{row.name}}</option></select></label><button :disabled="!product||p.busy.value" @click="p.link(product)">{{t('shop.link')}}</button><button v-if="p.moreProducts.value" @click="p.loadProducts(true)">{{t('account.more')}}</button><button v-if="p.moreLinked.value" @click="p.linked()">{{t('account.more')}}</button><article v-for="row in p.state.value.products" :key="row.id"><strong>{{row.name}} · {{formatAmount(row.price,'CNY')}}</strong><button :disabled="p.busy.value" @click="p.link(row.id,true)">{{t('shop.unlink')}}</button></article></template>
<form v-else @submit.prevent="p.apply()"><fieldset :disabled="p.busy.value||!!p.pending.value"><legend>{{t('shop.apply')}}</legend><label>{{t('shop.businessName')}}<input v-model="p.application.businessName" maxlength="200" required/></label><label>{{t('shop.creditCode')}}<input v-model="p.application.creditCode" maxlength="18" required/></label><label>{{t('shop.representative')}}<input v-model="p.application.representative" maxlength="100" required/></label><label>{{t('shop.invitation')}}<input v-model="p.application.invitationCode" maxlength="16"/></label><label>{{t('shop.license')}}<input type="file" accept="image/jpeg,image/png,application/pdf" @change="upload"/></label><select v-model="p.application.licenseUploadId"><option value="">{{t('shop.selectLicense')}}</option><option v-for="file in p.uploads.value.filter(f=>!f.consumed_at)" :key="String(file.id)" :value="String(file.id)">{{file.original_name||file.id}}</option></select><p>{{t('upload.privateNotice')}}</p><button>{{t('shop.apply')}}</button></fieldset><button v-if="p.pending.value" :disabled="p.busy.value">{{t('case.retryPending')}}</button></form>
<article v-for="row in p.state.value?.applications||[]" :key="row.id"><strong>{{row.business_name}} · {{t(shopStatusKey(row.status))}}</strong><p>{{row.review_note||''}} · {{formatDate(row.created_at)}}</p><button @click="download(row.license_upload_id)">{{t('shop.license')}}</button></article></template>
<article v-if="p.publicShop.value"><h3>{{p.publicShop.value.name}}</h3><p>{{p.publicShop.value.description}}</p><button v-if="p.morePublic.value" @click="p.preview(p.publicShop.value.id,true)">{{t('account.more')}}</button><p v-for="row in p.publicShop.value.products" :key="row.id"><a :href="'#services/product-detail?id='+encodeURIComponent(row.id)">{{row.name}} · {{formatAmount(row.price,'CNY')}}</a></p></article></section></template>
<style scoped>.shop-centre{display:grid;gap:12px}.shop-centre form,.shop-centre fieldset{display:grid;gap:12px}.shop-centre label{display:grid;gap:6px}.shop-centre input,.shop-centre select,.shop-centre textarea{padding:10px;max-width:100%}.shop-centre article{border-top:1px solid #cbd5e1;padding:16px 0}.shop-centre button{padding:9px;cursor:pointer}.shop-centre [role=alert]{color:#b42318}</style>
